147	  private simplifyPaths(paths: Set<string>): string[] {
148	    if (paths.size === 0) return [];
149	    const rawPaths = Array.from(paths);
150	
151	    // 1. Remove redundant paths (subpaths of already included paths)
152	    const sorted = rawPaths.sort((a, b) => a.length - b.length);
153	    const nonRedundant: string[] = [];
154	    for (const p of sorted) {
155	      if (!nonRedundant.some((s) => isSubpath(s, p))) {
156	        nonRedundant.push(p);
157	      }
158	    }
159	
160	    // 2. Consolidate clusters: if >= 3 paths share the same immediate parent, use the parent
161	    const parentCounts = new Map<string, string[]>();
162	    for (const p of nonRedundant) {
163	      const parent = path.dirname(p);
164	      if (!parentCounts.has(parent)) {
165	        parentCounts.set(parent, []);
166	      }
167	      parentCounts.get(parent)!.push(p);
168	    }
169	
170	    const finalPaths = new Set<string>();
171	
172	    const sensitiveDirs = new Set([
173	      os.homedir(),
174	      path.dirname(os.homedir()),
175	      path.sep,
176	      path.join(path.sep, 'etc'),
177	      path.join(path.sep, 'usr'),
178	      path.join(path.sep, 'var'),
179	      path.join(path.sep, 'bin'),
180	      path.join(path.sep, 'sbin'),
181	      path.join(path.sep, 'lib'),
182	      path.join(path.sep, 'root'),
183	      path.join(path.sep, 'home'),
184	      path.join(path.sep, 'Users'),
185	    ]);
186	
187	    if (os.platform() === 'win32') {
188	      const systemRoot = process.env['SystemRoot'];
189	      if (systemRoot) {
190	        sensitiveDirs.add(systemRoot);
191	        sensitiveDirs.add(path.join(systemRoot, 'System32'));
192	      }
193	      const programFiles = process.env['ProgramFiles'];
194	      if (programFiles) sensitiveDirs.add(programFiles);
195	      const programFilesX86 = process.env['ProgramFiles(x86)'];
196	      if (programFilesX86) sensitiveDirs.add(programFilesX86);
197	    }
198	
199	    for (const [parent, children] of parentCounts.entries()) {
200	      const isSensitive = sensitiveDirs.has(parent);
201	      if (children.length >= 3 && parent.length > 1 && !isSensitive) {
202	        finalPaths.add(parent);
203	      } else {
204	        for (const child of children) {
205	          finalPaths.add(child);
206	        }
207	      }
208	    }
209	
210	    // 3. Final redundancy check after consolidation
211	    const finalSorted = Array.from(finalPaths).sort(
212	      (a, b) => a.length - b.length,
213	    );
214	    const result: string[] = [];
215	    for (const p of finalSorted) {
216	      if (!result.some((s) => isSubpath(s, p))) {
217	        result.push(p);
218	      }
219	    }
220	
221	    return result;
222	  }
